const inputRoot = $json || {};

function safeJsonParse(value, fallback = {}) {
  if (value === null || value === undefined) return fallback;
  if (typeof value === "object") return value;
  if (typeof value !== "string") return fallback;

  const text = value.trim();
  if (!text) return fallback;

  try {
    return JSON.parse(text);
  } catch (error) {
    return fallback;
  }
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (typeof value === "string" && value.trim()) return value.trim();
    if (typeof value !== "string" && value) return value;
  }
  return "";
}

function hasFileLike(input) {
  return Boolean(
    input.file ||
    input.document ||
    input.photo ||
    input.telegram_file_id ||
    input.file_id ||
    input.input?.file ||
    input.input?.document ||
    input.input?.telegram_file_id ||
    input.request?.file ||
    input.request?.message?.document ||
    input.request?.message?.photo ||
    input.message?.document ||
    input.message?.photo
  );
}

function looksLikeJobDescription(text) {
  const value = String(text || "").trim();
  const lower = value.toLowerCase();

  if (value.length < 50) return false;

  const keywords = [
    "requirements",
    "responsibilities",
    "qualifications",
    "experience",
    "skills",
    "job description",
    "we are looking",
    "developer",
    "engineer",
    "frontend",
    "backend",
    "full stack",
    "react",
    "javascript",
    "position",
    "role",
    "candidate",
    "وظيفة",
    "المتطلبات",
    "المهارات",
    "خبرة",
    "مطلوب"
  ];

  return keywords.some(k => lower.includes(k.toLowerCase())) || value.length >= 120;
}

// =======================
// Read request/session
// =======================

const request = inputRoot.request || inputRoot;
const input = request.input || inputRoot.input || inputRoot;

const activeSession =
  inputRoot.active_session ||
  inputRoot.session ||
  request.active_session ||
  {};

const sessionContext = safeJsonParse(
  activeSession.context_json,
  activeSession.context_json || {}
);

const previousMatch =
  sessionContext.match ||
  inputRoot.match_context ||
  {};

// =======================
// Current input detection
// =======================

const messageText = firstNonEmpty(
  input.text,
  input.message_text,
  input.user_text,
  input.caption,
  input.message?.text,
  input.message?.caption,
  request.message?.text,
  request.message?.caption,
  request.request?.message?.text,
  request.request?.message?.caption,
  ""
);

const currentHasFile = hasFileLike(inputRoot) || hasFileLike(input);

const currentJobDescription = looksLikeJobDescription(messageText)
  ? messageText
  : "";

// =======================
// Existing CV analysis
// =======================

let analysis = {};

try {
  analysis = $("Last CV Analysis").first().json || {};
} catch (error) {
  analysis = {};
}

const analysisJson = safeJsonParse(
  analysis.analysis_json,
  analysis.full_analysis || analysis.analysis || {}
);

const technicalSkills =
  analysisJson.technicalSkills ||
  analysisJson.skills ||
  analysis.technicalSkills ||
  [];

const projects =
  analysisJson.projects ||
  analysis.projects ||
  [];

const experience =
  analysisJson.experience ||
  analysis.experience ||
  [];

const hasCvAnalysis =
  Boolean(
    previousMatch.has_cv_analysis ||
    analysis.analysis_id ||
    Object.keys(analysisJson).length > 0 ||
    analysis.overall_summary ||
    analysisJson.summary ||
    technicalSkills.length ||
    projects.length ||
    experience.length
  );

// =======================
// Merge old + current match context
// =======================

const jobDescription =
  currentJobDescription ||
  previousMatch.job_description ||
  "";

const hasJobDescription =
  Boolean(jobDescription && String(jobDescription).trim().length >= 50);

const hasCvFile =
  Boolean(currentHasFile || previousMatch.has_cv_file);

const readyToMatch =
  hasJobDescription && hasCvAnalysis;

const missing = [];

if (!hasJobDescription) missing.push("job_description");
if (!hasCvAnalysis) missing.push("cv_analysis");

const chatId = String(
  inputRoot.chat_id ||
  inputRoot.chatId ||
  request.chat_id ||
  request.chatId ||
  request.meta?.chat_id ||
  request.request?.meta?.chat_id ||
  input.chat_id ||
  input.chatId ||
  analysis.chat_id ||
  analysisJson.chatId ||
  ""
);

const userId =
  inputRoot.user_id ||
  inputRoot.user?.id ||
  request.user_id ||
  request.user?.id ||
  analysis.user_id ||
  analysisJson.userId ||
  null;

const sessionId =
  activeSession.id ||
  inputRoot.session_id ||
  request.session_id ||
  analysis.session_id ||
  analysisJson.sessionId ||
  null;

return [
  {
    json: {
      ok: true,
      success: true,
      status: "match_state_prepared",

      workflow: "WF_14_Match_CV_With_Job",

      // مهم جدًا: نحافظ على الطلب الأصلي عشان نرسله لـ WF_11 لو المستخدم رفع CV
      request,
      input,
      original_request: request,
      original_input: input,
      active_session: activeSession,

      chat_id: chatId,
      user_id: userId,
      session_id: sessionId,

      input_detection: {
        message_text: messageText,
        has_file: currentHasFile,
        detected_job_description: Boolean(currentJobDescription)
      },

      match_context: {
        job_description: jobDescription,
        has_job_description: hasJobDescription,

        has_cv_file: hasCvFile,
        has_cv_analysis: hasCvAnalysis,

        ready_to_match: readyToMatch,
        missing
      },

      cv_context: {
        candidate_name:
          analysisJson.candidateName ||
          analysis.candidateName ||
          "",

        detected_domain:
          analysis.detected_domain ||
          analysisJson.detectedDomain ||
          "",

        summary:
          analysis.overall_summary ||
          analysis.summary ||
          analysisJson.summary ||
          "",

        scores: {
          ats_score: Number(analysis.ats_score || analysisJson.atsScore || 0),
          recruiter_score: Number(analysis.recruiter_score || analysisJson.recruiterScore || 0),
          overall_score: Number(analysis.overall_score || analysisJson.overallScore || 0)
        },

        skills: technicalSkills,
        projects,
        experience,
        education: analysisJson.education || analysis.education || [],
        strengths: analysisJson.strengths || analysis.strengths || [],
        weaknesses: analysisJson.weaknesses || analysis.weaknesses || [],
        full_analysis: analysisJson
      },

      session_update: {
        active_service: "MATCH_CV_WITH_JOB",
        current_step: readyToMatch ? "ready_to_match" : "job_description_or_cv",
        status: readyToMatch ? "active" : "waiting_for_match_inputs",
        context_json: {
          match: {
            job_description: jobDescription,
            has_job_description: hasJobDescription,
            has_cv_file: hasCvFile,
            has_cv_analysis: hasCvAnalysis,
            ready_to_match: readyToMatch,
            missing
          },
          next_expected_input: readyToMatch
            ? "READY_TO_MATCH"
            : missing.includes("cv_analysis")
              ? "CV_FILE"
              : "JOB_DESCRIPTION"
        }
      }
    }
  }
];

const payload = $input.first().json || {};

// =======================
// Resolve match result
// =======================

const m =
  payload.match_result ||
  payload.match_db_payload?.match_result ||
  {};

// =======================
// Helpers
// =======================

function arr(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value.filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(/\n|•|,|،/)
      .map(x => x.trim())
      .filter(Boolean);
  }

  return [];
}

function list(items, emptyText = "• لا يوجد") {
  const values = arr(items);

  if (!values.length) return emptyText;

  return values
    .slice(0, 8)
    .map(item => `• ${item}`)
    .join("\n");
}

function safeText(value, fallback = "غير محدد") {
  const text = String(value || "").trim();
  return text || fallback;
}

// =======================
// Score / Level
// =======================

const score = Number(
  m.match_score ||
  payload.match_db_payload?.match_score ||
  0
);

let scoreEmoji = "🔴";
let scoreLabel = "Weak Match";

if (score >= 85) {
  scoreEmoji = "🟢";
  scoreLabel = "Strong Match";
} else if (score >= 70) {
  scoreEmoji = "🟡";
  scoreLabel = "Good Match";
} else if (score >= 50) {
  scoreEmoji = "🟠";
  scoreLabel = "Partial Match";
}

const matchLevel = safeText(
  m.match_level || payload.match_db_payload?.match_level,
  scoreLabel
);

// =======================
// Sections
// =======================

const keywordMatch = m.keyword_match || payload.match_db_payload?.keyword_match_json || {};
const experienceAlignment = m.experience_alignment || payload.match_db_payload?.experience_alignment_json || {};
const skillsAlignment = m.skills_alignment || payload.match_db_payload?.skills_alignment_json || {};

const matchedRequirements = arr(
  m.matched_requirements ||
  payload.match_db_payload?.matched_requirements_json
);

const missingOrWeakRequirements = arr(
  m.missing_or_weak_requirements ||
  payload.match_db_payload?.missing_or_weak_requirements_json
);

const matchedKeywords = arr(keywordMatch.matched_keywords);
const missingKeywords = arr(keywordMatch.missing_keywords);
const weakKeywords = arr(keywordMatch.weak_keywords);

const matchedSkills = arr(skillsAlignment.matched_skills);
const missingSkills = arr(skillsAlignment.missing_skills);
const transferableSkills = arr(skillsAlignment.transferable_skills);

const experienceMatchedPoints = arr(experienceAlignment.matched_experience_points);
const experienceMissingPoints = arr(experienceAlignment.missing_experience_points);

const recommendations = arr(
  m.top_recommendations ||
  payload.match_db_payload?.top_recommendations_json
);

// =======================
// Build text response
// =======================

const reportText =
`${scoreEmoji} نتيجة مطابقة CV مع الوظيفة

📊 Match Score: ${score}/100
📌 Level: ${matchLevel}

🧾 الملخص العام:
${safeText(m.overall_summary || payload.match_db_payload?.overall_summary, "لا يوجد ملخص متاح.")}

✅ المتطلبات المتطابقة:
${list(matchedRequirements)}

⚠️ المتطلبات الناقصة أو الضعيفة:
${list(missingOrWeakRequirements)}

🔑 الكلمات المفتاحية المتطابقة:
${list(matchedKeywords)}

❌ الكلمات المفتاحية الناقصة:
${list(missingKeywords)}

🟨 الكلمات المفتاحية الضعيفة:
${list(weakKeywords)}

🛠️ توافق المهارات:
المهارات المتطابقة:
${list(matchedSkills)}

المهارات الناقصة:
${list(missingSkills)}

مهارات قابلة للنقل:
${list(transferableSkills)}

💼 توافق الخبرة:
${safeText(experienceAlignment.summary, "غير محدد")}

نقاط الخبرة المتطابقة:
${list(experienceMatchedPoints)}

فجوات الخبرة:
${list(experienceMissingPoints)}

🚀 أفضل التوصيات قبل التقديم:
${list(recommendations)}

✅ التوصية النهائية:
${safeText(
  m.final_recommendation || payload.match_db_payload?.final_recommendation,
  "راجع المتطلبات الناقصة قبل التقديم."
)}`;

// =======================
// Return
// =======================

return [
  {
    json: {
      ok: true,
      success: true,
      status: "match_text_response_built",

      request_id: payload.request_id || "",
      chat_id: payload.chat_id || "",
      user_id: payload.user_id || payload.match_db_payload?.user_id || "",
      session_id: payload.session_id || payload.match_db_payload?.session_id || "",
      cv_analysis_id: payload.cv_analysis_id || payload.match_db_payload?.cv_analysis_id || "",

      match_result: m,
      match_db_payload: payload.match_db_payload || null,
      job_description: payload.job_description || payload.match_db_payload?.job_description || "",
      job_match_report_saved: payload.job_match_report_saved || false,
      db_save_result: payload.db_save_result || null,

      reply: {
        type: "text",
        text: reportText,
        buttons: [
          {
            label: "🎯 مطابقة وظيفة أخرى",
            action: "MATCH_CV_WITH_JOB"
          },
          {
            label: "🏠 القائمة الرئيسية",
            action: "MAIN_MENU"
          }
        ],
        file: null
      },

      meta: {
        source_workflow: "WF_14_Match_CV_With_Job",
        report_saved: payload.job_match_report_saved || false
      }
    }
  }
];

const matchState = $("Prepare Match State").first().json || {};
const analysisResult = $json || {};

function safeJsonParse(value, fallback = {}) {
  if (value === null || value === undefined) return fallback;
  if (typeof value === "object") return value;
  if (typeof value !== "string") return fallback;

  const text = value.trim();
  if (!text) return fallback;

  try {
    return JSON.parse(text);
  } catch (error) {
    return fallback;
  }
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (typeof value === "string" && value.trim()) return value.trim();
    if (typeof value !== "string" && value) return value;
  }
  return "";
}

// اقرأ context القديم من الجلسة حتى لا ننسى job_description
const activeSession = matchState.active_session || {};
const sessionContext = safeJsonParse(
  activeSession.context_json,
  activeSession.context_json || {}
);

const sessionMatchContext =
  sessionContext.match ||
  {};

// نتيجة تحليل CV القادمة من WF_11 قد تأتي بأكثر من شكل
const analysis =
  analysisResult.analysis ||
  analysisResult.cv_analysis ||
  analysisResult.data?.analysis ||
  analysisResult.analysis_json ||
  analysisResult.full_analysis ||
  analysisResult;

const analysisJson = safeJsonParse(
  analysis.analysis_json || analysis,
  analysis
);

const hasCvAnalysis = Boolean(
  analysisResult.ok === true ||
  analysisResult.success === true ||
  analysisResult.status === "cv_analysis_saved" ||
  analysisResult.status === "cv_analysis_completed" ||
  analysisResult.status === "analyze_response_built" ||
  Object.keys(analysisJson).length > 0
);

// مهم جدًا: لا تعتمد على matchState فقط
// خذ job_description من:
// 1. matchState الحالي
// 2. active_session.context_json
// 3. analysisResult لو موجود
const jobDescription = firstNonEmpty(
  matchState.match_context?.job_description,
  sessionMatchContext.job_description,
  analysisResult.job_description,
  analysisResult.match_context?.job_description,
  ""
);

const hasJobDescription =
  Boolean(jobDescription && jobDescription.trim().length >= 50);

const readyToMatch =
  hasCvAnalysis && hasJobDescription;

const missing = [];
if (!hasCvAnalysis) missing.push("cv_analysis");
if (!hasJobDescription) missing.push("job_description");

const updatedCvContext = {
  candidate_name: firstNonEmpty(
    analysisJson.candidateName,
    analysisJson.candidate_name,
    analysisJson.full_name,
    analysisJson.name,
    matchState.cv_context?.candidate_name,
    ""
  ),

  detected_domain: firstNonEmpty(
    analysisJson.detectedDomain,
    analysisJson.detected_domain,
    analysisJson.currentRole,
    matchState.cv_context?.detected_domain,
    ""
  ),

  summary: firstNonEmpty(
    analysisJson.summary,
    analysisJson.overall_summary,
    analysisJson.overallSummary,
    matchState.cv_context?.summary,
    ""
  ),

  scores: {
    ats_score: Number(
      analysisJson.atsScore ||
      analysisJson.ats_score ||
      matchState.cv_context?.scores?.ats_score ||
      0
    ),
    recruiter_score: Number(
      analysisJson.recruiterScore ||
      analysisJson.recruiter_score ||
      matchState.cv_context?.scores?.recruiter_score ||
      0
    ),
    overall_score: Number(
      analysisJson.overallScore ||
      analysisJson.overall_score ||
      matchState.cv_context?.scores?.overall_score ||
      0
    )
  },

  skills:
    analysisJson.technicalSkills ||
    analysisJson.skills ||
    matchState.cv_context?.skills ||
    [],

  projects:
    analysisJson.projects ||
    matchState.cv_context?.projects ||
    [],

  experience:
    analysisJson.experience ||
    matchState.cv_context?.experience ||
    [],

  education:
    analysisJson.education ||
    matchState.cv_context?.education ||
    [],

  strengths:
    analysisJson.strengths ||
    matchState.cv_context?.strengths ||
    [],

  weaknesses:
    analysisJson.weaknesses ||
    matchState.cv_context?.weaknesses ||
    [],

  full_analysis: analysisJson
};

return [
  {
    json: {
      ...matchState,

      status: "match_state_updated_with_cv_analysis",

      match_context: {
        ...matchState.match_context,

        job_description: jobDescription,
        has_job_description: hasJobDescription,

        has_cv_file: true,
        has_cv_analysis: hasCvAnalysis,

        ready_to_match: readyToMatch,
        missing
      },

      cv_context: updatedCvContext,

      session_update: {
        ...matchState.session_update,
        active_service: "MATCH_CV_WITH_JOB",
        current_step: readyToMatch ? "ready_to_match" : "job_description_or_cv",
        status: readyToMatch ? "active" : "waiting_for_match_inputs",
        context_json: {
          match: {
            job_description: jobDescription,
            has_job_description: hasJobDescription,
            has_cv_file: true,
            has_cv_analysis: hasCvAnalysis,
            ready_to_match: readyToMatch,
            missing
          },
          next_expected_input: readyToMatch
            ? "READY_TO_MATCH"
            : missing.includes("job_description")
              ? "JOB_DESCRIPTION"
              : "CV_FILE"
        }
      },

      analysis_source: {
        workflow: "WF_11_Analyze_CV",
        status: analysisResult.status || "",
        ok: analysisResult.ok === true,
        success: analysisResult.success === true
      }
    }
  }
];

const input = $json || {};

const sessionId = input.session_id || input.active_session?.id || null;

const sessionUpdate = input.session_update || {};

if (!sessionId) {
  return [
    {
      json: {
        ...input,
        ok: false,
        success: false,
        status: "match_session_update_failed",
        error: {
          code: "SESSION_ID_MISSING",
          message: "Cannot update match session because session_id is missing."
        }
      }
    }
  ];
}

const currentStep =
  sessionUpdate.current_step ||
  "job_description_or_cv";

const status =
  sessionUpdate.status ||
  "waiting_for_match_inputs";

const contextJson =
  sessionUpdate.context_json ||
  {
    match: {
      job_description: input.match_context?.job_description || "",
      has_job_description: input.match_context?.has_job_description || false,
      has_cv_file: input.match_context?.has_cv_file || false,
      has_cv_analysis: input.match_context?.has_cv_analysis || false,
      ready_to_match: input.match_context?.ready_to_match || false,
      missing: input.match_context?.missing || []
    },
    next_expected_input: "JOB_DESCRIPTION_OR_CV"
  };

return [
  {
    json: {
      ...input,
      match_session_update_payload: {
        session_id: sessionId,
        current_step: currentStep,
        status,
        context_json: contextJson
      }
    }
  }
];

const state = $("Prepare Match Session Update Payload").first().json || {};
const dbResult = $json || {};

return [
  {
    json: {
      ...state,
      db_update_result: dbResult,
      session_context_saved: true
    }
  }
];

const current = $input.first().json || {};

const req =
  current.request && Object.keys(current.request).length
    ? current.request
    : current.original_request || current;

const session =
  req.session ||
  current.session ||
  current.active_session ||
  {};

const user =
  req.user ||
  current.user ||
  {};

const matchContext =
  current.match_context ||
  session.context_json?.match ||
  {};

const jobDescription =
  matchContext.job_description ||
  current.job_description ||
  req.input?.text ||
  "";

const cvAnalysis =
  current.cv_analysis || {};

const analysis =
  cvAnalysis.analysis_json || {};

const cvForMatching = {
  candidate_name:
    analysis.candidateName ||
    analysis.candidate_name ||
    "",

  current_role:
    analysis.currentRole ||
    "",

  professional_summary:
    analysis.summary ||
    "",

  technical_skills:
    analysis.technicalSkills || [],

  soft_skills:
    analysis.softSkills || [],

  experience:
    analysis.experience || [],

  projects:
    analysis.projects || [],

  education:
    analysis.education || [],

  certifications:
    analysis.certifications || [],

  languages:
    analysis.languages || [],

  detected_domain:
    analysis.detectedDomain ||
    "",

  cv_text:
    cvAnalysis.cv_text || ""
};

const totalSkillCount =
  cvForMatching.technical_skills.length +
  cvForMatching.soft_skills.length;

const hasJobDescription =
  String(jobDescription || "").trim().length > 50;

const hasCvContext =
  Boolean(cvForMatching.professional_summary) ||
  totalSkillCount > 0 ||
  cvForMatching.experience.length > 0 ||
  cvForMatching.projects.length > 0 ||
  String(cvForMatching.cv_text || "").trim().length > 100;

if (
  !hasJobDescription ||
  !hasCvContext ||
  !cvAnalysis.has_cv_analysis_row
) {
  return [{
    json: {
      ok: false,
      success: false,
      status: "match_ai_input_not_ready",

      chat_id:
        req.meta?.chat_id ||
        current.chat_id ||
        user.channel_user_id ||
        "",

      user_id:
        Number(user.id || current.user_id || 0),

      session_id:
        Number(session.id || current.session_id || 0),

      error: {
        code: "MATCH_INPUT_NOT_READY",
        message:
          "CV analysis and job description are required."
      }
    }
  }];
}

const outputSchema = {
  match_score: 0,
  match_level: "",
  overall_summary: "",
  matched_requirements: [],
  missing_or_weak_requirements: [],
  keyword_match: {
    matched_keywords: [],
    missing_keywords: [],
    weak_keywords: [],
    transferable_keywords: []
  },
  experience_alignment: {
    level: "",
    summary: "",
    matched_experience_points: [],
    missing_experience_points: []
  },
  skills_alignment: {
    matched_skills: [],
    missing_skills: [],
    weak_skills: [],
    transferable_skills: []
  },
  top_recommendations: [],
  final_recommendation: ""
};

return [{
  json: {
    ok: true,
    success: true,
    status: "match_ai_input_ready",

    workflow: "WF_14_Match_CV_With_Job",

    request_id:
      req.request_id ||
      current.request_id ||
      "",

    chat_id:
      req.meta?.chat_id ||
      current.chat_id ||
      user.channel_user_id ||
      "",

    user_id:
      Number(user.id || current.user_id || 0),

    session_id:
      Number(session.id || current.session_id || 0),

    cv_analysis_id:
      Number(cvAnalysis.id || 0),

    job_description: jobDescription,

    cv_for_matching: cvForMatching,

    output_schema: outputSchema,

    match_meta: {
      service: "MATCH_CV_WITH_JOB",
      language:
        req.context?.language ||
        user.language_code ||
        "en",

      technical_skill_count:
        cvForMatching.technical_skills.length,

      soft_skill_count:
        cvForMatching.soft_skills.length
    }
  }
}];

const aiItem = $input.first().json || {};
const base = $("Build Match AI Input").first().json || {};

// =======================
// Helpers
// =======================

function getAiText(input) {
  return String(
    input.output ||
    input.text ||
    input.response ||
    input.content ||
    input.message?.content ||
    input.data?.output ||
    ''
  );
}

function extractJson(text) {
  let t = String(text || '').trim();

  t = t.replace(/^```json\s*/i, '');
  t = t.replace(/^```\s*/i, '');
  t = t.replace(/```$/i, '');
  t = t.trim();

  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');

  if (first >= 0 && last > first) {
    return t.slice(first, last + 1);
  }

  return t;
}

