}

const matchScore = num(match.match_score || 0);

let matchLevel = str(match.match_level || '');

if (!matchLevel) {
  if (matchScore >= 85) matchLevel = 'Strong Match';
  else if (matchScore >= 70) matchLevel = 'Good Match';
  else if (matchScore >= 50) matchLevel = 'Partial Match';
  else matchLevel = 'Weak Match';
}

